def C(label,prompt,answer,wrong,why):return dict(type='choice',label=label,selectionPrompt=prompt,answer=answer,options=[answer,*wrong],explanation=why)
def N(label,prompt,answer,why,tolerance=0):return dict(type='numeric',label=label,selectionPrompt=prompt,answer=answer,tolerance=tolerance,explanation=why)
