 out[f'organic-2-{n}']={'fields':fields,'complete':not limited,'scope':'Checks every displayed objective response. Original freehand drawing production is not automatically assessed.' if limited else 'Checks all requested final answers and displayed reasoning choices.','reviewNotice':note,'references':['https://openstax.org/books/organic-chemistry/pages/2-3-formal-charges','https://openstax.org/books/organic-chemistry/pages/2-5-rules-for-resonance-forms']}
